files.alarms.js:
// This dash's alarm rules, for the kit's engine and banner (kit/alarms.js, kit/alarm_banner.js). The
// temperature alarms sit at the starts of their channels' red and warn zones (ranges.js: the same
// lines the dials draw), so moving a zone moves its alarm. Values are base units.
import { CHANNELS, num } from './kit/channels.js';
import { leanest } from './kit/alarms.js';
import { oilMin } from './kit/oil.js';
import { LAMBDA_PARKED } from './ranges.js';

const running = (r) => (r.rpm ?? 0) > 400;
const lean = (r) => leanest(r, LAMBDA_PARKED);

// A temperature's red and amber alarms, each clearing `back` degrees below.
function tooHot(id, key, text, back) {
  const at = (zone) => CHANNELS[key][zone][0][0];
  return [
    { id: `${id}-red`, sev: 'red', key, text, holdMs: 2000, on: (r) => num(r[key]) >= at('red'), off: (r) => !(num(r[key]) >= at('red') - back) },
    { id: `${id}-warn`, sev: 'warn', key, text, holdMs: 3000, on: (r) => num(r[key]) >= at('warn'), off: (r) => !(num(r[key]) >= at('warn') - back) },
  ];
}

// key: the channel the banner quotes (lean: how lean, for the mixture alarms); on(r) / off(r): true
// when the alarm should set / may clear.
export const ALARMS = [
  { id: 'oil-low', sev: 'red', key: 'oil_kpa', text: 'OIL PRESSURE LOW', holdMs: 1000,
    on: (r) => running(r) && r.rpm > 1000 && num(r.oil_kpa) !== null && r.oil_kpa < 70, off: (r) => !running(r) || r.oil_kpa > 85 },
  // the oil envelope (ranges.js OIL): about 10 psi (69 kPa) per 1000 rpm
  { id: 'oil-low-rpm', sev: 'warn', key: 'oil_kpa', text: 'OIL PRESSURE LOW FOR RPM', holdMs: 2000,
    on: (r) => running(r) && r.rpm > 1500 && num(r.oil_kpa) !== null && r.oil_kpa < oilMin(r.rpm), off: (r) => !running(r) || r.oil_kpa > oilMin(r.rpm) * 1.09 },
  ...tooHot('head', 'ect_c', 'HEAD TEMP HIGH', 5),
  ...tooHot('oilt', 'oil_temp_c', 'OIL TEMP HIGH', 3),
  // lean under load is what hurts an engine; light-throttle and overrun readings don't count
  { id: 'lean-red', sev: 'red', key: 'lambda', lean, text: 'LEAN UNDER LOAD', holdMs: 500,
    on: (r) => running(r) && (r.tps_pct ?? 0) > 50 && lean(r) > 0.08, off: (r) => !((r.tps_pct ?? 0) > 40 && lean(r) > 0.05) },
  { id: 'lean-warn', sev: 'warn', key: 'lambda', lean, text: 'LEAN UNDER LOAD', holdMs: 1000,
    on: (r) => running(r) && (r.tps_pct ?? 0) > 50 && lean(r) > 0.05, off: (r) => !((r.tps_pct ?? 0) > 40 && lean(r) > 0.03) },
  { id: 'fuel-low', sev: 'red', key: 'fuel_kpa', text: 'FUEL PRESSURE LOW', holdMs: 1000, on: (r) => running(r) && num(r.fuel_kpa) !== null && r.fuel_kpa < 250, off: (r) => !running(r) || r.fuel_kpa > 265 },
  { id: 'batt-red', sev: 'red', key: 'battery_v', text: 'BATTERY', holdMs: 5000, on: (r) => running(r) && num(r.battery_v) !== null && (r.battery_v < 11.8 || r.battery_v > 15.2), off: (r) => !running(r) || (r.battery_v > 12.2 && r.battery_v < 15) },
  { id: 'charge', sev: 'warn', key: 'battery_v', text: 'NOT CHARGING', holdMs: 10000, on: (r) => running(r) && r.rpm > 1500 && num(r.battery_v) !== null && r.battery_v < 12.6, off: (r) => !running(r) || r.battery_v > 13 },
];

files.box_list.js:
// The boxes the TunerLoop dash's panels show, and what each automatic mode shows. Data only, no
// imports, so the unit tests and the Screens page read it as it is (boxes.js makes them).
// Every box a panel can show, one list for both panels (sideways swipes loop through it; a long press
// opens a menu of them). A box is a dial, Lambda's dual dial, the G meter, or the grid of every number.
// row: its row of pages a swipe down (pages.js ROWS): 'dial' (the dial, its graphs, then 15 minutes,
// today and 30 days full screen; compass: a compass page second), 'g' (the meter, its compass), 'grid'
// (3 by 3 a panel page); none, itself then itself full screen. units: the kind of units a box shows
// when its own key doesn't say (units.js), for the two-finger tap that changes them.
// All numbers, in the order its pages show them: the nine read most first (a panel page holds 3 by 3).
export const GRID_KEYS = ['rpm', 'speed_kmh', 'oil_kpa', 'oil_temp_c', 'ect_c', 'battery_v', 'lambda1', 'lambda2', 'tps_pct',
  'iat_c', 'fuel_kpa', 'map_kpa', 'ign_deg', 'lambda_target'];

export const BOXES = [
  { id: 'tach', name: 'Tach', kind: 'gauge', key: 'rpm', row: 'dial' },
  { id: 'speed', name: 'Speed', kind: 'big', key: 'speed_kmh', row: 'dial' },
  { id: 'g', name: 'G meter', kind: 'g', row: 'g' },
  { id: 'oil', name: 'Oil pressure', kind: 'big', key: 'oil_kpa', row: 'dial' },
  { id: 'oilt', name: 'Oil temp', kind: 'big', key: 'oil_temp_c', row: 'dial' },
  { id: 'grid', name: 'All numbers', kind: 'grid', keys: GRID_KEYS, row: 'grid' },
  { id: 'twin', name: 'Lambda', kind: 'twindial', key: 'lambda1', units: 'mixture', row: 'dial', compass: 'mix' },   // the dual dial (kit/twin_dial.js), both banks, the banks' compass
  { id: 'head', name: 'Head temp', kind: 'big', key: 'ect_c', row: 'dial' },
  { id: 'battery', name: 'Battery', kind: 'big', key: 'battery_v', row: 'dial' },
  { id: 'iat', name: 'Intake air', kind: 'big', key: 'iat_c', row: 'dial' },
  { id: 'fuel', name: 'Fuel pressure', kind: 'big', key: 'fuel_kpa', row: 'dial' },
];
export const START = ['tach', 'twin'];   // what each panel shows until someone picks another

// What each automatic mode (kit/automodes.js) shows over a panel while it lasts.
export const AUTO_BOXES = {
  pull: { kind: 'pull' }, corner: { kind: 'g' }, warm: { kind: 'big', key: 'oil_temp_c' },
  stop: { kind: 'grid', keys: ['oil_kpa', 'oil_temp_c', 'ect_c', 'battery_v'] },
};

// Boxes that take the whole reading rather than one channel's value.
export const WHOLE = new Set(['grid', 'twindial', 'g', 'pull']);

export const THEMES = [['modern', 'Modern'], ['vintage', 'Vintage Flat'], ['vintage3d', 'Vintage 3D'], ['race', 'Race']];

files.boxes.js:
// Making the TunerLoop dash's boxes (the list: box_list.js), each drawn by a kit module.
import { CHANNELS } from './kit/channels.js';
import { makeGauge, makeBig, makeGrid } from './kit/gauge.js';
import { makeTwinDial } from './kit/twin_dial.js';
import { makeG, makePull } from './kit/phone_boxes.js';

export function makeBox(spec) {
  if (spec.kind === 'gauge') return makeGauge(spec.key);
  if (spec.kind === 'big') return makeBig(spec.key);
  if (spec.kind === 'twindial') return makeTwinDial();
  if (spec.kind === 'g') return makeG();
  if (spec.kind === 'pull') return makePull();
  return makeGrid(spec.keys || Object.keys(CHANNELS));
}

files.dash.css:
/* The TunerLoop dash's layout (index.js, panels.js): two panels filling the Car tab, stacked when
   upright and side by side sideways, the full screen layer over them, a box's pages and the groove
   between two sliding pages, the dots, and the long-press menu. Theme colours and type: the kit's
   themes.css; the boxes' own styles: the kit's boxes.css. */
.dash { position: absolute; inset: 0; background: #000; }   /* the whole Car tab is ours: the gaps between the panels too */
.panels { display: grid; grid-template-rows: 1fr 1fr; gap: 9px; height: 100%; transition: opacity 0.4s; }
.dash[data-mode="dim"] .panels { opacity: 0.35; }
@media (orientation: landscape) { .panels { grid-template-rows: 1fr; grid-template-columns: 1fr 1fr; } }
.dots { position: absolute; left: 0; right: 0; bottom: 6px; display: flex; justify-content: center; gap: 6px; pointer-events: none; transition: opacity 0.3s; }
.dots i { width: 6px; height: 6px; border-radius: 50%; background: var(--d-label); opacity: 0.4; }
.dots i.on { opacity: 1; }

/* ---------------------------------------------------------------- pages (pages.js): what a panel or full screen shows */
.page { position: absolute; inset: 0; will-change: transform; }
.page[hidden] { display: none; }
/* The full screen layer over the panels (panels.js): one panel's full screen page */
.panel.dash-full { position: absolute; inset: 0; z-index: 3; will-change: transform; }
.panel.dash-full[hidden] { display: none; }
.dash[data-mode="dim"] .dash-full { opacity: 0.35; }
.dash.sliding { overflow: hidden; }   /* the panels grid and the layer sliding past each other */
.panels { will-change: transform; }
/* The dots and the page's name show while a page moves (panels.js flashDots), then fade. */
.lvdots, .lvname, .dots { opacity: 0; transition: opacity 0.4s; }
.panel.dots-on :is(.lvname, .dots), .pagedots.dots-on .lvdots { opacity: 1; transition: opacity 0.1s; }
/* A panel's page dots, over where the panel sits and outside everything that slides (panels.js pageDots) */
.pagedots { position: absolute; z-index: 4; pointer-events: none; }
.pagedots[hidden] { display: none; }
.dash[data-mode="dim"] .pagedots { opacity: 0.35; }
/* Between two pages while they slide: a groove with the name of the page coming in */
.pagesep { position: fixed; top: 0; left: 0; height: 30px; z-index: 6; pointer-events: none; display: flex; align-items: center; justify-content: center;
  background: linear-gradient(#000, #111 45%, #0a0a0a); border-top: 1px solid rgba(255, 255, 255, 0.07); border-bottom: 1px solid rgba(0, 0, 0, 0.9);
  box-shadow: 0 0 10px rgba(0, 0, 0, 0.8); will-change: transform; }
.pagesep[hidden] { display: none; }
.pagesep span { color: var(--d-label); font: 600 11px/1 var(--d-font); letter-spacing: 0.14em; text-transform: uppercase; }
.lvdots { position: absolute; right: 8px; top: 50%; transform: translateY(-50%); display: flex; flex-direction: column; gap: 8px; z-index: 2; pointer-events: none; }
.lvdots i { width: 7px; height: 7px; border-radius: 50%; background: var(--d-label); opacity: 0.35; }
.lvdots i.on { opacity: 1; background: var(--d-value); }
.lvname { position: absolute; left: 50%; bottom: 8px; transform: translateX(-50%); z-index: 2; pointer-events: none; color: var(--d-label); font: 600 12px/1 var(--d-font); letter-spacing: 0.1em; text-transform: uppercase; }

/* ---------------------------------------------------------------- the long-press menu: every box, filling the panel */
.jump { position: absolute; inset: 0; z-index: 4; display: grid; grid-template-columns: repeat(3, 1fr); grid-auto-rows: 1fr; gap: 1.5cqmin; padding: 1.5cqmin; box-sizing: border-box; background: rgba(0, 0, 0, 0.92); }
.jump button { margin: 0; padding: 0 1cqmin; min-width: 0; min-height: 0; border: 1px solid var(--d-grid); border-radius: 2cqmin; background: var(--d-track); color: var(--d-value); font: 600 clamp(14px, 5cqmin, 24px)/1.1 var(--d-font); }
.jump button.on { background: var(--d-value); color: var(--d-face); border-color: var(--d-value); }

/* ---------------------------------------------------------------- its settings (settings.js), opened by the app's gear */
.dset { position: absolute; inset: 0; z-index: 7; display: flex; flex-direction: column; gap: 2cqmin; padding: 3cqmin; box-sizing: border-box; overflow: auto; background: #000; color: var(--d-value); font: 600 clamp(14px, 4cqmin, 20px)/1.2 var(--d-font); }
.dset h4 { margin: 1cqmin 0 0; color: var(--d-label); font: inherit; font-size: 0.8em; letter-spacing: 0.1em; text-transform: uppercase; }
.dset .row { display: grid; grid-template-columns: repeat(auto-fit, minmax(9em, 1fr)); gap: 1.5cqmin; }
.dset p { margin: 0; color: var(--d-label); }
.dset button { margin: 0; min-height: 48px; padding: 0 1em; border: 1px solid var(--d-grid); border-radius: 2cqmin; background: var(--d-track); color: var(--d-value); font: inherit; }
.dset button.on { background: var(--d-value); color: var(--d-face); border-color: var(--d-value); }
.dset .done { margin-top: auto; }
/* The app's tab bar handle takes the bottom 60px (the right 60px sideways) while the tab bar is hidden
   (the app's css/car_tab.css .nav-pull): the panel keeps its buttons out of it. */
.dset { padding-bottom: calc(3cqmin + 64px); }
@media (orientation: landscape) { .dset { padding-bottom: 3cqmin; padding-right: calc(3cqmin + 64px); } }

files.index.js:
// The TunerLoop dash: the Car tab's built-in dash (../../../../ecuai/docs/plan-dashes.md). Two panels
// of boxes and a full screen layer, each box a row of pages (panels.js), the automatic modes, the
// alarm banner, and the light in Vintage 3D following the phone's tilt. Fork it
// (scripts/fork_dash.mjs), give dash.json a new id, change what you like.
//
// Its limits (zones, valid ranges, the oil envelope, the warm-up point) are its own, in ranges.js; its
// alarm rules in alarms.js. The redline follows the car's tune (api.tune.rev_limit). Its settings
// (gauge style, automatic modes) are its own too, in settings.js, opened by the app's gear.
//
// Data comes from the app: each reading (base units, with the phone's speed, g and tilt and the 0-60
// timer); the phone's recent history at start; stored history on request (kit/trend_data.js).
import { hist } from './kit/hist.js';
import { useUnits } from './kit/units.js';
import { useChannels } from './kit/channels.js';
import { useOil } from './kit/oil.js';
import { setSteadyHz } from './kit/steady.js';
import { setTrendSource } from './kit/trend_data.js';
import { autoStep } from './kit/automodes.js';
import { showAlarms } from './kit/alarm_banner.js';
import { moveLight } from './kit/light.js';
import { D3_DEFS } from './kit/d3defs.js';
import { createPanels } from './panels.js';
import { startFrom } from './start.js';
import { RANGES, OIL, WARM_BELOW_C } from './ranges.js';
import { ALARMS } from './alarms.js';
import { loadSettings, openSettings } from './settings.js';


export default function mount(api) {
  const root = api.root, start = startFrom(api.params);
  let s = loadSettings(api.store);
  root.dataset.theme = start?.theme || s.style;
  root.insertAdjacentHTML('beforeend', D3_DEFS);
  // Before anything is drawn: this dash's ranges, the redline from the tune when the app has it.
  const redline = () => redlineFrom(api.tune);
  useChannels(RANGES);
  useChannels(redlineRanges(redline().rpm));
  useOil(OIL);
  useUnits(api.units);
  setTrendSource({ call: (name, body) => api.request('trend', { name, body }), bridge: () => api.bridge });
  if (api.history) hist.restore(api.history);
  const panels = createPanels(root, api, start);
  // Under a test address the automatic modes are off unless it asks for them (auto=1): the simulated
  // drive keeps setting them off.
  const autosFrom = (x) => (start && !start.auto ? {} : { pull: x.auto_pull, corner: x.auto_corner, stop: x.auto_stop, warm: x.auto_warm, warmBelow: WARM_BELOW_C });
  let autoOn = autosFrom(s);
  api.on('settings', () => openSettings(root, api, s, redline, (next) => {
    const restyle = next.style !== s.style && !start?.theme;
    s = next;
    autoOn = autosFrom(s);
    if (restyle) { root.dataset.theme = s.style; panels.rebuild(); }
  }));
  // A new tune read: the redline moves with it.
  api.on('tune', () => { useChannels(redlineRanges(redline().rpm)); panels.rebuild(); });

  let value = null, smooth = 70, autoSt = {};
  api.on('reading', (v, t, m) => {
    value = v;
    smooth = m.smoothMs ?? 70;
    setSteadyHz(m.digitsHz);
    root.dataset.mode = m.dim ? 'dim' : '';
    hist.tick(t);
    if (!m.dim) hist.push(v, t);   // late readings aren't charted: the charts stop until new ones come
  });
  api.on('units', (u) => { useUnits(u); panels.rebuild(); });
  api.on('fonts', panels.rebuildViews);   // charts drew before the theme fonts arrived

  let last = 0;
  requestAnimationFrame(function frame(now) {
    requestAnimationFrame(frame);
    const dt = last ? Math.min(250, now - last) : 16;
    last = now;
    if (root.dataset.theme === 'vintage3d') moveLight(root, value, now);
    const auto = autoStep(autoSt, value, Date.now(), autoOn);
    autoSt = auto.st;
    panels.draw({ value, dt, smoothMs: smooth, now }, [auto.left, auto.right]);
    showAlarms(root, value, now, ALARMS);
  });
}

// The redline: the tune's rev limit, else the one in ranges.js. Red from there to the end of
// the scale; the Pull view's shift light 800 rpm before it.
const AS_FOUND = RANGES.rpm.red[0][0];
export function redlineFrom(tune) {
  const rpm = tune?.rev_limit;
  return Number.isFinite(rpm) && rpm >= 2000 && rpm <= 20000 ? { rpm, fromTune: true } : { rpm: AS_FOUND, fromTune: false };
}
export function redlineRanges(rpm) {
  const top = Math.max(RANGES.rpm.red[0][1], Math.ceil((rpm + 500) / 1000) * 1000);
  return { rpm: { red: [[rpm, top]], shift: rpm - 800 } };
}

files.kit/alarm_banner.js:
// kit/alarm_banner.js: the app's kit/alarm_banner.js as forked with tunerloop-dash. Yours to change.
// The alarm banner: runs the alarm check (alarms.js) with a dash's rules on each frame and shows the
// worst firing alarm in words, with the reading, across the bottom of the dash. Red fills the
// banner and is spoken once; amber is a slimmer strip. A tap snoozes that alarm for a minute (it
// comes back if it is still true). Speech needs one tap first on iPhone, so the first touch on the
// dash unlocks it.
import { checkAlarms } from './alarms.js';
import { CHANNELS, shown } from './channels.js';

const SNOOZE_MS = 60000, CHECK_MS = 200;
let state = {}, lastCheck = 0, el = null, showing = null, spokeAt = {}, voiceOn = false;
const snoozed = {};

// The banner text: what, and the reading in the chosen unit.
function alarmText(a, r) {
  if (a.lean) { const e = a.lean(r); return e === null ? a.text : `${a.text} · +${(e * 100).toFixed(0)}%`; }
  const ch = shown(CHANNELS[a.key]), t = ch.text(r?.[a.key]);
  return t === '-' ? a.text : `${a.text} · ${t}${ch.unit ? ' ' + ch.unit : ''}`;
}

function speak(text) {
  if (!voiceOn || !window.speechSynthesis) return;
  try { speechSynthesis.cancel(); speechSynthesis.speak(new SpeechSynthesisUtterance(text.replace(/·.*/, '').toLowerCase())); } catch { /* no voice */ }
}

function ensure(root) {
  if (el) return el;
  el = document.createElement('button');
  el.type = 'button'; el.className = 'alarm'; el.hidden = true;
  el.addEventListener('click', () => { if (showing) snoozed[showing.id] = Date.now() + SNOOZE_MS; el.hidden = true; showing = null; });
  root.append(el);
  root.addEventListener('pointerdown', () => {   // unlock speech on the first touch (iPhone)
    if (voiceOn || !window.speechSynthesis) return;
    try { speechSynthesis.speak(new SpeechSynthesisUtterance('')); voiceOn = true; } catch { /* no voice */ }
  }, { once: false });
  return el;
}

// r: the live reading (base units, or null); now: ms (performance.now or Date.now: only differences
// matter); rules: the dash's alarm rules (alarms.js).
export function showAlarms(root, r, now, rules) {
  const b = ensure(root);
  if (now - lastCheck < CHECK_MS) return;
  lastCheck = now;
  const out = checkAlarms(state, r, now, rules);
  state = out.state;
  const wall = Date.now();
  const top = out.active.find((a) => !(snoozed[a.id] > wall));
  if (!top) { if (!b.hidden) b.hidden = true; showing = null; return; }
  const text = alarmText(top, r);
  if (b.textContent !== text) b.textContent = text;
  b.dataset.sev = top.sev;
  b.hidden = false;
  if (top.sev === 'red' && !(spokeAt[top.id] > wall - SNOOZE_MS)) { spokeAt[top.id] = wall; speak(top.text); }
  showing = top;
}

files.kit/alarms.js:
// kit/alarms.js: the app's kit/alarms.js as forked with tunerloop-dash. Yours to change.
// The alarm engine: a pure check of each live reading against a dash's rules, MoTeC/AiM style. A rule
// fires only when its condition holds for holdMs, and only under its qualifier (engine running, revs
// up, under load), so start-up and idle don't cry wolf. It clears at a separate, gentler level
// (hysteresis), so a reading sitting on the limit doesn't flicker the banner. Red alarms take the
// banner and are spoken; amber ones show in a strip (alarm_banner.js). Values are base units.
// The rules are a dash's own (the built-in dash's alarms.js): { id, sev: 'red'|'warn', key (the channel
// the banner quotes), text, holdMs, on(r), off(r) }.
import { num } from './channels.js';

// The leaner bank's error against the target (0.05 = 5 % lean), or null without readings. max: a
// wideband reading at or past it is a parked controller, not a mixture.
export function leanest(r, max = Infinity) {
  const t = num(r?.lambda_target) ?? 1, ls = [num(r?.lambda1), num(r?.lambda2)].filter((x) => x !== null && x < max);
  return ls.length ? Math.max(...ls) / t - 1 : null;
}

// One step. state: { [id]: { since, active } } from the last call ({} to start); r: the reading
// (base units); now: ms. Returns { state, active } with active the firing alarms, red first, and
// within a channel only the most severe (a red head temp hides the amber one).
export function checkAlarms(state, r, now, rules) {
  const next = {}, active = [];
  for (const a of rules) {
    const was = state[a.id] || { since: null, active: false };
    let { since, active: on } = was;
    if (!r) { since = null; on = false; }
    else if (on) { if (a.off(r)) { on = false; since = null; } }
    else if (a.on(r)) { since = since ?? now; if (now - since >= a.holdMs) on = true; }
    else since = null;
    next[a.id] = { since, active: on };
    if (on) active.push(a);
  }
  const rank = (a) => (a.sev === 'red' ? 0 : 1);
  active.sort((x, y) => rank(x) - rank(y));
  const seen = new Set();
  return { state: next, active: active.filter((a) => (seen.has(a.key) ? false : seen.add(a.key))) };
}

files.kit/automodes.js:
// kit/automodes.js: the app's kit/automodes.js as forked with tunerloop-dash. Yours to change.
// Automatic modes: for a while a Car tab panel shows what the moment needs, then hands back.
//   Hard acceleration: full throttle and pulling -> the Pull view (RPM, speed, 0-60 or 50-70 timer).
//   Cornering: past 0.5 g -> the G meter, held 6 s after the last big g.
//   Stoplight: stopped 3 s -> oil pressure, oil temp, head temp, battery; back above 8 km/h (5 mph).
//   Warm-up: oil under the dash's warm-up point (on.warmBelow, deg C) -> oil temp on the right panel.
// Hard acceleration beats Cornering beats Stoplight (all left panel); Warm-up is the right panel.
// Which are on, and the warm-up point, are the dash's (its settings and ranges). autoStep is pure,
// so it is tested without a page.

// st: last state ({} to start); r: the reading (speed_kmh, g_lat, g_long from the phone; tps_pct,
// oil_temp_c from the car); now: ms; on: { pull, corner, stop, warm } and warmBelow.
// Returns { st, left, right }: a mode key or null for each panel.
export function autoStep(st, r, now, on) {
  const s = { stillSince: null, stopped: false, cornerUntil: -1, pullOff: null, pulling: false, holdPull: -1, ...st };
  const v = r?.speed_kmh, gl = r?.g_lat, ga = r?.g_long;
  // stoplight: still for 3 s; clears above 8 km/h
  if (typeof v === 'number') {
    if (v < 1.6) { s.stillSince = s.stillSince ?? now; if (now - s.stillSince >= 3000) s.stopped = true; }
    else { s.stillSince = null; if (v > 8) s.stopped = false; }
  } else { s.stillSince = null; s.stopped = false; }
  // cornering: total g past 0.5
  if (typeof gl === 'number' && typeof ga === 'number' && Math.hypot(gl, ga) > 0.5) s.cornerUntil = now + 6000;
  // hard acceleration: throttle over 85 % and pulling (phone g when there is one); ends 1 s after lifting, result shown 5 s
  const pullingNow = (r?.tps_pct ?? 0) > 85 && (typeof ga === 'number' ? ga > 0.25 : (r?.rpm ?? 0) > 2500);
  if (pullingNow) { s.pulling = true; s.pullOff = null; }
  else if (s.pulling) { s.pullOff = s.pullOff ?? now; if (now - s.pullOff > 1000) { s.pulling = false; s.holdPull = now + 5000; } }
  let left = null;
  if (on.pull && (s.pulling || now < s.holdPull)) left = 'pull';
  else if (on.corner && now < s.cornerUntil) left = 'corner';
  else if (on.stop && s.stopped) left = 'stop';
  const right = on.warm && typeof r?.oil_temp_c === 'number' && r.oil_temp_c < on.warmBelow ? 'warm' : null;
  return { st: s, left, right };
}

