    chartBg: v('--d-chart-bg', 'rgba(0,0,0,0.25)'), chartNum: v('--d-chart-num', ''), chartTagInk: v('--d-chart-tag-ink', ''), chartGlow: +v('--d-chart-glow', '0') || 0,
